code.cpp:
class Solution {
public:
    int minFallingPathSum(vector<vector<int>>& grid) {
        int n = grid.size();
        if (n == 1) return grid[0][0];

        vector<int> dp(grid[0].begin(), grid[0].end());

        for (int i = 1; i < n; i++) {
            int min1 = INT_MAX, min2 = INT_MAX, idx1 = -1;
            for (int j = 0; j < n; j++) {
                if (dp[j] < min1) {
                    min2 = min1;
                    min1 = dp[j];
                    idx1 = j;
                } else if (dp[j] < min2) {
                    min2 = dp[j];
                }
            }

            vector<int> newDp(n);
            for (int j = 0; j < n; j++) {
                newDp[j] = grid[i][j] + (j == idx1 ? min2 : min1);
            }
            dp = move(newDp);
        }

        return *min_element(dp.begin(), dp.end());
    }
};
